import { useParams } from "react-router-dom";
import { useEffect, useState } from "react";

import "./Product.css";

function Product() {
  const { id } = useParams();
  const [prod, setProd] = useState([]);
  useEffect(() => {
    fetch("https://dummyjson.com/products")
      .then((res) => res.json())
      .then((res) => setProd(res.products));
  }, []);

  const productData = prod.filter((elm) => elm.id === Number(id))[0];

  console.log(productData);

  return <div key={productData.id}>
<img src={productData[0].images} alt="product" />
<div className="discription">
    <h2>{productData[0].title}</h2>
    <h3>Category: {productData[0].category}</h3>
</div>
  </div>;
}

export default Product;
